{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Ziprasidone, a lipophilic piperazine-containing drug, has an absolute oral bioavailability of about 60% in the fed state in healthy volunteers, directly matching the fed-state condition and supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Asciminib has an absolute oral bioavailability of approximately 73% in humans, demonstrating that a complex oral drug can achieve high systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sertindole has an oral bioavailability of approximately 74% in humans and is not significantly affected by food, supporting high F for a lipophilic, poorly soluble drug under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Apixaban has an oral bioavailability of 49% in humans at clinical doses, another moderate-to-high F example.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Diltiazem has an absolute oral bioavailability of 38 ± 11% in humans despite extensive hepatic first-pass metabolism, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Rizatriptan has an absolute oral bioavailability of approximately 40% in male volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A predicted human oral bioavailability of 23% for a related compound is the lowest retrieved value and still exceeds the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence points to oral bioavailability values ≥ 23%, with most analogues in the 38–75% range; direct fed-state data for ziprasidone show ~60% F. No retrieved evidence supports F < 20%, so the query is predicted to have high absolute oral bioavailability at the F ≥ 20% threshold under fed conditions.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the query molecule; all evidence is from analogues with high transfer scores.",
    "Fed-state-specific data are available for ziprasidone and sertindole, but not for the exact query molecule.",
    "The query is a large, poorly water-soluble azole; solubility-limited absorption could introduce variability, but the fed condition and analogue range suggest F remains above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

